struct ip6_hdr {
  union {
    struct ip6_hdrctl {
      uint32_t ip6_un1_flow;   /* 24ビットのフローID */
      uint16_t ip6_un1_plen;   /* ペイロード長 */
      uint8_t  ip6_un1_nxt;    /* 次ヘッダー */
      uint8_t  ip6_un1_hlim;   /* ホップリミット */
    } ip6_un1;
    uint8_t ip6_un2_vfc;       /* 4ビットのバージョン、4ビットの優先度 */
  } ip6_ctlun;
  struct in6_addr ip6_src;      /* 送信元アドレス */
  struct in6_addr ip6_dst;      /* 宛先アドレス */
};

#define ip6_vfc   ip6_ctlun.ip6_un2_vfc
#define ip6_flow  ip6_ctlun.ip6_un1.ip6_un1_flow
#define ip6_plen  ip6_ctlun.ip6_un1.ip6_un1_plen
#define ip6_nxt   ip6_ctlun.ip6_un1.ip6_un1_nxt
#define ip6_hlim  ip6_ctlun.ip6_un1.ip6_un1_hlim
#define ip6_hops  ip6_ctlun.ip6_un1.ip6_un1_hlim

/* ホップバイホップオプションヘッダー */
/* XXX 8バイト境界にアラインメントさせるためにパディングすべきか？ */
struct ip6_hbh {
  uint8_t  ip6h_nxt;        /* 次ヘッダー */
  uint8_t  ip6h_len;        /* 8オクテット単位の長さ */
    /* この後にオプションが続く */
};

/* 宛先オプションヘッダー */
/* XXX 8バイト境界にアラインメントさせるためにパディングすべきか？ */
struct ip6_dest {
  uint8_t  ip6d_nxt;        /* 次ヘッダー */
  uint8_t  ip6d_len;        /* 8オクテット単位の長さ */
    /* この後にオプションが続く */
};

/* ルーティングヘッダー */
struct ip6_rthdr {
  uint8_t  ip6r_nxt;        /* 次ヘッダー */
  uint8_t  ip6r_len;        /* 8オクテット単位の長さ */
  uint8_t  ip6r_type;       /* ルーティングタイプ */
  uint8_t  ip6r_segleft;    /* 残りセグメント数 */
    /* この後にルーティングタイプ固有のデータが続く */
};

/* タイプ0ルーティングヘッダー */
struct ip6_rthdr0 {
  uint8_t  ip6r0_nxt;       /* 次ヘッダー */
  uint8_t  ip6r0_len;       /* 8オクテット単位の長さ */
  uint8_t  ip6r0_type;      /* 常にゼロ */
  uint8_t  ip6r0_segleft;   /* 残りセグメント数 */
  uint8_t  ip6r0_reserved;  /* 予約済みフィールド */
  uint8_t  ip6r0_slmap[3];  /* strict/looseビットマップ */
  struct in6_addr  ip6r0_addr[1];  /* 最大23個のアドレス */
};

/* フラグメントヘッダー */
struct ip6_frag {
  uint8_t   ip6f_nxt;       /* 次ヘッダー */
  uint8_t   ip6f_reserved;  /* 予約済みフィールド */
  uint16_t  ip6f_offlg;     /* オフセット、予約済み、フラグ */
  uint32_t  ip6f_ident;     /* 識別子 */
};

#if     BYTE_ORDER == BIG_ENDIAN
#define IP6F_OFF_MASK       0xfff8  /* _offlgからオフセットを取り出すマスク */
#define IP6F_RESERVED_MASK  0x0006  /* ip6f_offlgの予約済みビット */
#define IP6F_MORE_FRAG      0x0001  /* more-fragmentsフラグ */
#else   /* BYTE_ORDER == LITTLE_ENDIAN */
#define IP6F_OFF_MASK       0xf8ff  /* _offlgからオフセットを取り出すマスク */
#define IP6F_RESERVED_MASK  0x0600  /* ip6f_offlgの予約済みビット */
#define IP6F_MORE_FRAG      0x0100  /* more-fragmentsフラグ */
#endif

struct icmp6_hdr {
  uint8_t     icmp6_type;   /* タイプフィールド */
  uint8_t     icmp6_code;   /* コードフィールド */
  uint16_t    icmp6_cksum;  /* チェックサムフィールド */
  union {
    uint32_t  icmp6_un_data32[1]; /* タイプ固有のフィールド */
    uint16_t  icmp6_un_data16[2]; /* タイプ固有のフィールド */
    uint8_t   icmp6_un_data8[4];  /* タイプ固有のフィールド */
  } icmp6_dataun;
};

#define icmp6_data32    icmp6_dataun.icmp6_un_data32
#define icmp6_data16    icmp6_dataun.icmp6_un_data16
#define icmp6_data8     icmp6_dataun.icmp6_un_data8
#define icmp6_pptr      icmp6_data32[0]  /* パラメーター問題 */
#define icmp6_mtu       icmp6_data32[0]  /* パケット過大 */
#define icmp6_id        icmp6_data16[0]  /* エコー要求/応答 */
#define icmp6_seq       icmp6_data16[1]  /* エコー要求/応答 */
#define icmp6_maxdelay  icmp6_data16[0]  /* マルチキャストグループメンバーシップ */

#define ND_ROUTER_SOLICIT           133
#define ND_ROUTER_ADVERT            134
#define ND_NEIGHBOR_SOLICIT         135
#define ND_NEIGHBOR_ADVERT          136
#define ND_REDIRECT                 137

struct nd_router_solicit {     /* ルーター要請 */
  struct icmp6_hdr  nd_rs_hdr;
    /* この後にオプションが続く場合がある */
};

#define nd_rs_type               nd_rs_hdr.icmp6_type
#define nd_rs_code               nd_rs_hdr.icmp6_code
#define nd_rs_cksum              nd_rs_hdr.icmp6_cksum
#define nd_rs_reserved           nd_rs_hdr.icmp6_data32[0]

struct nd_router_advert {      /* ルーター広告 */
  struct icmp6_hdr  nd_ra_hdr;
  uint32_t   nd_ra_reachable;   /* 到達可能時間 */
  uint32_t   nd_ra_retransmit;  /* 再送タイマー */
    /* この後にオプションが続く場合がある */
};

#define nd_ra_type               nd_ra_hdr.icmp6_type
#define nd_ra_code               nd_ra_hdr.icmp6_code
#define nd_ra_cksum              nd_ra_hdr.icmp6_cksum
#define nd_ra_curhoplimit        nd_ra_hdr.icmp6_data8[0]
#define nd_ra_flags_reserved     nd_ra_hdr.icmp6_data8[1]
#define ND_RA_FLAG_MANAGED       0x80
#define ND_RA_FLAG_OTHER         0x40
#define nd_ra_router_lifetime    nd_ra_hdr.icmp6_data16[1]

struct nd_neighbor_solicit {   /* 近隣要請 */
  struct icmp6_hdr  nd_ns_hdr;
  struct in6_addr   nd_ns_target; /* ターゲットアドレス */
    /* この後にオプションが続く場合がある */
};

#define nd_ns_type               nd_ns_hdr.icmp6_type
#define nd_ns_code               nd_ns_hdr.icmp6_code
#define nd_ns_cksum              nd_ns_hdr.icmp6_cksum
#define nd_ns_reserved           nd_ns_hdr.icmp6_data32[0]

struct nd_neighbor_advert {    /* 近隣広告 */
  struct icmp6_hdr  nd_na_hdr;
  struct in6_addr   nd_na_target; /* ターゲットアドレス */
    /* この後にオプションが続く場合がある */
};

#define nd_na_type               nd_na_hdr.icmp6_type
#define nd_na_code               nd_na_hdr.icmp6_code
#define nd_na_cksum              nd_na_hdr.icmp6_cksum
#define nd_na_flags_reserved     nd_na_hdr.icmp6_data32[0]
#if     BYTE_ORDER == BIG_ENDIAN
#define ND_NA_FLAG_ROUTER        0x80000000
#define ND_NA_FLAG_SOLICITED     0x40000000
#define ND_NA_FLAG_OVERRIDE      0x20000000
#else   /* BYTE_ORDER == LITTLE_ENDIAN */
#define ND_NA_FLAG_ROUTER        0x00000080
#define ND_NA_FLAG_SOLICITED     0x00000040
#define ND_NA_FLAG_OVERRIDE      0x00000020
#endif

struct nd_redirect {           /* リダイレクト */
  struct icmp6_hdr  nd_rd_hdr;
  struct in6_addr   nd_rd_target; /* ターゲットアドレス */
  struct in6_addr   nd_rd_dst;    /* 宛先アドレス */
    /* この後にオプションが続く場合がある */
};

#define nd_rd_type               nd_rd_hdr.icmp6_type
#define nd_rd_code               nd_rd_hdr.icmp6_code
#define nd_rd_cksum              nd_rd_hdr.icmp6_cksum
#define nd_rd_reserved           nd_rd_hdr.icmp6_data32[0]

struct nd_opt_hdr {           /* 近隣探索オプションヘッダー */
  uint8_t  nd_opt_type;
  uint8_t  nd_opt_len;        /* 8オクテット単位 */
    /* この後にオプション固有のデータが続く */
};

#define  ND_OPT_SOURCE_LINKADDR       1
#define  ND_OPT_TARGET_LINKADDR       2
#define  ND_OPT_PREFIX_INFORMATION    3
#define  ND_OPT_REDIRECTED_HEADER     4
#define  ND_OPT_MTU                   5

struct nd_opt_prefix_info {    /* プレフィックス情報 */
  uint8_t   nd_opt_pi_type;
  uint8_t   nd_opt_pi_len;
  uint8_t   nd_opt_pi_prefix_len;
  uint8_t   nd_opt_pi_flags_reserved;
  uint32_t  nd_opt_pi_valid_time;
  uint32_t  nd_opt_pi_preferred_time;
  uint32_t  nd_opt_pi_reserved2;
  struct in6_addr  nd_opt_pi_prefix;
};

#define ND_OPT_PI_FLAG_ONLINK        0x80
#define ND_OPT_PI_FLAG_AUTO          0x40

struct nd_opt_rd_hdr {         /* リダイレクトされたヘッダー */
  uint8_t   nd_opt_rh_type;
  uint8_t   nd_opt_rh_len;
  uint16_t  nd_opt_rh_reserved1;
  uint32_t  nd_opt_rh_reserved2;
    /* この後にIPヘッダーとデータが続く */
};

struct nd_opt_mtu {            /* MTUオプション */
  uint8_t   nd_opt_mtu_type;
  uint8_t   nd_opt_mtu_len;
  uint16_t  nd_opt_mtu_reserved;
  uint32_t  nd_opt_mtu_mtu;
};

struct protoent  *proto;

proto = getprotobyname("icmp");

s = socket(AF_INET, SOCK_RAW, proto->p_proto);

void ICMP6_FILTER_SETPASSALL (struct icmp6_filter *);
void ICMP6_FILTER_SETBLOCKALL(struct icmp6_filter *);

void ICMP6_FILTER_SETPASS ( int, struct icmp6_filter *);
void ICMP6_FILTER_SETBLOCK( int, struct icmp6_filter *);

int  ICMP6_FILTER_WILLPASS (int, const struct icmp6_filter *);
int  ICMP6_FILTER_WILLBLOCK(int, const struct icmp6_filter *);

struct icmp6_filter  myfilt;

fd = socket(PF_INET6, SOCK_RAW, IPPROTO_ICMPV6);

ICMP6_FILTER_SETBLOCKALL(&myfilt);
ICMP6_FILTER_SETPASS(ND_ROUTER_ADVERT, &myfilt);
setsockopt(fd, IPPROTO_ICMPV6, ICMP6_FILTER, &myfilt, sizeof(myfilt));

struct msghdr {
  void      *msg_name;        /* ソケットアドレス構造体へのポインター */
  socklen_t  msg_namelen;     /* ソケットアドレス構造体のサイズ */
  struct iovec  *msg_iov;     /* スキャッター/ギャザー配列 */
  size_t     msg_iovlen;      /* msg_iovの要素数 */
  void      *msg_control;     /* 補助データ */
  socklen_t  msg_controllen;  /* 補助データバッファーの長さ */
  int        msg_flags;       /* 受信したメッセージのフラグ */
};

struct cmsghdr {
  socklen_t  cmsg_len;   /* このヘッダーを含むバイト数 */
  int        cmsg_level; /* 発信元のプロトコル */
  int        cmsg_type;  /* プロトコル固有のタイプ */
             /* この後に unsigned char cmsg_data[]; が続く */
};

struct msghdr   msg;
struct cmsghdr  *cmsgptr;

/* msgを埋める */

/* recvmsg()を呼び出す */

for (cmsgptr = CMSG_FIRSTHDR(&msg); cmsgptr != NULL;
     cmsgptr = CMSG_NXTHDR(&msg, cmsgptr)) {
    if (cmsgptr->cmsg_level == ... && cmsgptr->cmsg_type == ... ) {
        u_char  *ptr;

        ptr = CMSG_DATA(cmsgptr);
        /* ptrが指すデータを処理する */
    }
}

struct msghdr  msg;
struct cmsghdr  *cmsgptr = NULL;

/* msgを埋める */

/* recvmsg()を呼び出す */

while ((cmsgptr = CMSG_NXTHDR(&msg, cmsgptr)) != NULL) {
    if (cmsgptr->cmsg_level == ... && cmsgptr->cmsg_type == ... ) {
        u_char  *ptr;

        ptr = CMSG_DATA(cmsgptr);
        /* ptrが指すデータを処理する */
    }
}

int  on = 1;

setsockopt(fd, IPPROTO_IPV6, IPV6_PKTINFO,  &on, sizeof(on));
setsockopt(fd, IPPROTO_IPV6, IPV6_HOPLIMIT, &on, sizeof(on));
setsockopt(fd, IPPROTO_IPV6, IPV6_HOPOPTS,  &on, sizeof(on));
setsockopt(fd, IPPROTO_IPV6, IPV6_DSTOPTS,  &on, sizeof(on));
setsockopt(fd, IPPROTO_IPV6, IPV6_RTHDR,    &on, sizeof(on));

struct in6_pktinfo {
  struct in6_addr ipi6_addr;    /* 送信元/宛先IPv6アドレス */
  unsigned int    ipi6_ifindex; /* 送信/受信インターフェースのインデックス */
};

        /* オプションXとオプションYは[RFC-1883]のpp. 33-34で定義されている */
#define IP6_X_OPT_TYPE       X   /* Xを割り当てられた値に置き換える */
#define IP6_X_OPT_LEN       12
#define IP6_X_OPT_MULTX      8   /* 8n + 2のアラインメント */
#define IP6_X_OPT_OFFSETY    2

struct ip6_X_opt {
  uint8_t   ip6_X_opt_pad[IP6_X_OPT_OFFSETY];
  uint8_t   ip6_X_opt_type;
  uint8_t   ip6_X_opt_len;
  uint32_t  ip6_X_opt_val1;
  uint64_t  ip6_X_opt_val2;
};

#define IP6_Y_OPT_TYPE       Y   /* Yを割り当てられた値に置き換える */
#define IP6_Y_OPT_LEN        7
#define IP6_Y_OPT_MULTX      4   /* 4n + 3のアラインメント */
#define IP6_Y_OPT_OFFSETY    3

struct ip6_Y_opt {
  uint8_t   ip6_Y_opt_pad[IP6_Y_OPT_OFFSETY];
  uint8_t   ip6_Y_opt_type;
  uint8_t   ip6_Y_opt_len;
  uint8_t   ip6_Y_opt_val1;
  uint16_t  ip6_Y_opt_val2;
  uint32_t  ip6_Y_opt_val3;
};

struct msghdr  msg;
struct cmsghdr  *cmsgptr;
struct ip6_X_opt  optX;
struct ip6_Y_opt  optY;

msg.msg_control = malloc(inet6_option_space(sizeof(optX) +
                                            sizeof(optY)));

inet6_option_init(msg.msg_control, &cmsgptr, IPV6_HOPOPTS);

optX.ip6_X_opt_type = IP6_X_OPT_TYPE;
optX.ip6_X_opt_len  = IP6_X_OPT_LEN;
optX.ip6_X_opt_val1 = <32-bit value>;
optX.ip6_X_opt_val2 = <64-bit value>;
inet6_option_append(cmsgptr, &optX.ip6_X_opt_type,
                    IP6_X_OPT_MULTX, IP6_X_OPT_OFFSETY);

optY.ip6_Y_opt_type = IP6_Y_OPT_TYPE;
optY.ip6_Y_opt_len  = IP6_Y_OPT_LEN;
optY.ip6_Y_opt_val1 = <8-bit value>;
optY.ip6_Y_opt_val2 = <16-bit value>;
optY.ip6_Y_opt_val3 = <32-bit value>;
inet6_option_append(cmsgptr, &optY.ip6_Y_opt_type,
                    IP6_Y_OPT_MULTX, IP6_Y_OPT_OFFSETY);

msg.msg_controllen = cmsgptr->cmsg_len;

struct msghdr  msg;
struct cmsghdr  *cmsgptr;
struct ip6_X_opt  optX;
struct ip6_Y_opt  optY;

msg.msg_control = malloc(inet6_option_space(sizeof(optX)) +
                         inet6_option_space(sizeof(optY)));

inet6_option_init(msg.msg_control, &cmsgptr, IPPROTO_HOPOPTS);

optX.ip6_X_opt_type = IP6_X_OPT_TYPE;
optX.ip6_X_opt_len  = IP6_X_OPT_LEN;
optX.ip6_X_opt_val1 = <32-bit value>;
optX.ip6_X_opt_val2 = <64-bit value>;
inet6_option_append(cmsgptr, &optX.ip6_X_opt_type,
                    IP6_X_OPT_MULTX, IP6_X_OPT_OFFSETY);
msg.msg_controllen = CMSG_SPACE(sizeof(optX));

inet6_option_init((u_char *)msg.msg_control + msg.msg_controllen,
                  &cmsgptr, IPPROTO_HOPOPTS);

optY.ip6_Y_opt_type = IP6_Y_OPT_TYPE;
optY.ip6_Y_opt_len  = IP6_Y_OPT_LEN;
optY.ip6_Y_opt_val1 = <8-bit value>;
optY.ip6_Y_opt_val2 = <16-bit value>;
optY.ip6_Y_opt_val3 = <32-bit value>;
inet6_option_append(cmsgptr, &optY.ip6_Y_opt_type,
                    IP6_Y_OPT_MULTX, IP6_Y_OPT_OFFSETY);
msg.msg_controllen += cmsgptr->cmsg_len;

uint8_t  *typep;
struct msghdr  msg;
struct cmsghdr  *cmsgptr;
struct ip6_X_opt  *optXp;  /* 構造体ではなくポインターになった */
struct ip6_Y_opt  *optYp;  /* 構造体ではなくポインターになった */

msg.msg_control = malloc(inet6_option_space(sizeof(*optXp) +
                                            sizeof(*optYp)));

inet6_option_init(msg.msg_control, &cmsgptr, IPV6_HOPOPTS);

typep = inet6_option_alloc(cmsgptr, IP6_X_OPT_LEN,
                           IP6_X_OPT_MULTX, IP6_X_OPT_OFFSETY);
optXp = (struct ip6_X_opt *) (typep - IP6_X_OPT_OFFSETY);
optXp->ip6_X_opt_type = IP6_X_OPT_TYPE;
optXp->ip6_X_opt_len  = IP6_X_OPT_LEN;
optXp->ip6_X_opt_val1 = <32-bit value>;
optXp->ip6_X_opt_val2 = <64-bit value>;

typep = inet6_option_alloc(cmsgptr, IP6_Y_OPT_LEN,
                           IP6_Y_OPT_MULTX, IP6_Y_OPT_OFFSETY);
optYp = (struct ip6_Y_opt *) (typep - IP6_Y_OPT_OFFSETY);
optYp->ip6_Y_opt_type = IP6_Y_OPT_TYPE;
optYp->ip6_Y_opt_len  = IP6_Y_OPT_LEN;
optYp->ip6_Y_opt_val1 = <8-bit value>;
optYp->ip6_Y_opt_val2 = <16-bit value>;
optYp->ip6_Y_opt_val3 = <32-bit value>;

msg.msg_controllen = cmsgptr->cmsg_len;

struct msghdr   msg;
struct cmsghdr  *cmsgptr;

/* msgを埋める */

/* recvmsg()を呼び出す */

for (cmsgptr = CMSG_FIRSTHDR(&msg); cmsgptr != NULL;
     cmsgptr = CMSG_NXTHDR(&msg, cmsgptr)) {
    if (cmsgptr->cmsg_level == IPPROTO_IPV6 &&
        cmsgptr->cmsg_type == IPV6_HOPOPTS) {

        uint8_t  *tptr = NULL;

        while (inet6_option_next(cmsgptr, &tptr) == 0) {
            if (*tptr == IP6_X_OPT_TYPE) {
                struct ip6_X_opt  *optXp;
                optXp = (struct ip6_X_opt *) (tptr - IP6_X_OPT_OFFSETY);
                <do whatever with> optXp->ip6_X_opt_val1;
                <do whatever with> optXp->ip6_X_opt_val2;

            } else if (*tptr == IP6_Y_OPT_TYPE) {
                struct ip6_Y_opt  *optYp;

                optYp = (struct ip6_Y_opt *) (tptr - IP6_Y_OPT_OFFSETY);
                <do whatever with> optYp->ip6_Y_opt_val1;
                <do whatever with> optYp->ip6_Y_opt_val2;
                <do whatever with> optYp->ip6_Y_opt_val3;
            }
        }
        if (tptr != NULL)
            <error encountered by inet6_option_next()>;
    }
}

void  *ptr;
struct msghdr  msg;
struct cmsghdr  *cmsgptr;
struct sockaddr_in6  I1, I2, I3, D;
unsigned int  f0, f1, f2, f3;

ptr = malloc(inet6_rthdr_space(IPV6_RTHDR_TYPE_0, 3));
cmsgptr = inet6_rthdr_init(ptr, IPV6_RTHDR_TYPE_0);

inet6_rthdr_add(cmsgptr, &I1.sin6_addr, f0);
inet6_rthdr_add(cmsgptr, &I2.sin6_addr, f1);
inet6_rthdr_add(cmsgptr, &I3.sin6_addr, f2);
inet6_rthdr_lasthop(cmsgptr, f3);

msg.msg_control = ptr;
msg.msg_controllen = cmsgptr->cmsg_len;

/* msg{}の残りを埋める。msg_name = D */
/* sendmsg()を呼び出す */
